// QA evidence helper only. Frozen product and acceptance harness unchanged.
export async function qa26SaveFreshScreenshotEvidence({sky,window,campaignRoot,predicateId,knownSHA256=[]}){if(!sky||typeof sky.get_window_state!=='function')throw Error('Fresh screenshot API required');if(!window?.id||!window?.app)throw Error('Exact source window required');if(!/^[a-zA-Z0-9_-]+$/.test(predicateId||''))throw Error('Safe predicate ID required');const captureRequestedUtc=new Date().toISOString();const snapshot=await sky.get_window_state({window});const captureReturnedUtc=new Date().toISOString();if(snapshot?.window?.id!==window.id||snapshot?.window?.app!==window.app)throw Error('Unexpected capture window; no evidence saved');if(snapshot.screenshots?.length!==1)throw Error('Exactly one unambiguous window screenshot required');const shot=snapshot.screenshots[0];const match=/^data:(image\/(?:jpeg|png));base64,([A-Za-z0-9+/=\r\n]+)$/.exec(shot.url||'');if(!match||!(shot.width>0)||!(shot.height>0))throw Error('Fresh image bytes and dimensions required');const fs=await import('node:fs/promises');const path=await import('node:path');const crypto=await import('node:crypto');const bytes=Buffer.from(match[2],'base64');if(!bytes.length)throw Error('Empty screenshot; no evidence saved');const sha256=crypto.createHash('sha256').update(bytes).digest('hex');if(Array.from(knownSHA256).some(h=>String(h).toLowerCase()===sha256))throw Error('Duplicate image bytes rejected; preserve pending case, do not repeat test automatically');const root=path.resolve(campaignRoot);const ext=match[1]==='image/png'?'png':'jpg';const relative='screenshots/'+predicateId+'_'+Date.now()+'_'+crypto.randomUUID()+'.'+ext;const absolute=path.resolve(root,...relative.split('/'));if(!absolute.startsWith(root+path.sep))throw Error('Evidence path escaped campaign');const receipt={schema:'QA26-FRESH-SCREENSHOT-EVIDENCE-1',predicateId,captureRequestedUtc,captureReturnedUtc,sourceWindow:{app:snapshot.window.app,id:snapshot.window.id,title:snapshot.window.title},sourceScreenshotId:shot.id,image:{width:shot.width,height:shot.height,mimeType:match[1],bytes:bytes.length,sha256},evidence:relative,freshQueryPerformed:true,cachedGlobalImageUsed:false,duplicateBytesRejected:true,qualification:'UNQUALIFIED_CAPTURE_ONLY',nativeDpi:'REQUIRES_SEPARATE_CONTEMPORANEOUS_NATIVE_EVIDENCE',assertionCredit:0,fullCellCredit:0};await fs.writeFile(absolute,bytes,{flag:'wx'});await fs.writeFile(absolute+'.capture.json',JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});return{snapshot,...receipt};}
